package com.edtech.platform.finance.util;
import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.Base64; import javax.crypto.Cipher; import javax.crypto.spec.GCMParameterSpec; import javax.crypto.spec.SecretKeySpec;
public final class AccountNumberCipher { private static final byte[] KEY=loadKey(); private static byte[] loadKey(){String value=System.getProperty("edtech.account-encryption-key",System.getenv("EDTECH_ACCOUNT_ENCRYPTION_KEY")); boolean prod="prod".equalsIgnoreCase(System.getProperty("spring.profiles.active",System.getenv("SPRING_PROFILES_ACTIVE"))); if(value==null||value.length()!=32){if(prod) throw new IllegalStateException("EDTECH_ACCOUNT_ENCRYPTION_KEY must be a 32-byte secret in production"); value="01234567890123456789012345678901";} return value.getBytes(StandardCharsets.UTF_8);} private static final SecureRandom RANDOM=new SecureRandom(); private AccountNumberCipher(){} public static String encrypt(String raw){if(raw==null||raw.isBlank())return raw;try{byte[] iv=new byte[12];RANDOM.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(KEY,"AES"),new GCMParameterSpec(128,iv));byte[] out=c.doFinal(raw.trim().getBytes(StandardCharsets.UTF_8));byte[] all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return "v1:"+Base64.getEncoder().encodeToString(all);}catch(Exception e){throw new IllegalStateException("account encryption failed",e);}} public static String decrypt(String encrypted){if(encrypted==null||encrypted.isBlank())return encrypted;try{if(!encrypted.startsWith("v1:"))return encrypted;byte[] all=Base64.getDecoder().decode(encrypted.substring(3));byte[] iv=java.util.Arrays.copyOfRange(all,0,12);byte[] data=java.util.Arrays.copyOfRange(all,12,all.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(KEY,"AES"),new GCMParameterSpec(128,iv));return new String(c.doFinal(data),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalArgumentException("invalid encrypted account number",e);}} public static String mask(String raw){if(raw==null||raw.isBlank())return "";String s=raw.trim();return s.length()<=4?s:"******"+s.substring(s.length()-4);} }
